INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007009', '2026-04-21-qwen3-6-max-preview', '阿里发布 Qwen3.6-Max 预览版：千问系列性能最强模型', '产品发布', '2026-04-21', '阿里发布了千问系列性能最强的大模型 Qwen3.6-Max-Preview。相比 Plus 版本，其在智能体编程、世界知识和指令遵循方面均有提升。千问 3.6 系列已推出多个版本并开源了 Qwen3.6-35B-A3B。', '[{"title":"QwenLM GitHub","url":"https://github.com/QwenLM/Qwen3"},{"title":"阿里云百炼","url":"https://bailian.console.aliyun.com/"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007010', '2026-04-21-kimi-k2-6', 'Kimi K2.6 发布并开源：支持300个Agent并行协作', '产品发布', '2026-04-21', '月之暗面发布并开源 Kimi K2.6 模型。该模型在通用 Agent、代码、视觉理解等方面表现优异，支持长程编码（连续 13 小时）和大规模 Agent 集群协作（300 个子 Agent 并行）。', '[{"title":"Kimi 官网","url":"https://www.kimi.com"},{"title":"月之暗面 GitHub","url":"https://github.com/moonshot-ai"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007011', '2026-04-21-openai-new-image-model', 'OpenAI 将于未来数周发布全新图像模型', '产品发布', '2026-04-21', 'OpenAI 宣布将在未来数周内发布全新的图像模型，新模型生成复杂图像和图表的能力将得到显著提升，预计将进一步缩小与竞争对手在图像生成领域的差距。', '[{"title":"OpenAI 官网","url":"https://openai.com"},{"title":"OpenAI API 文档","url":"https://platform.openai.com/docs"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007012', '2026-04-21-alibaba-happyhorse', '阿里 HappyHorse 将于4月27日开放测试，5月正式商用', '产品发布', '2026-04-21', '阿里 ATH 宣布 HappyHorse-1.0 将于 4 月 27 日通过阿里云百炼平台逐步开放 API 测试，首批邀测对象为企业级客户，计划于 5 月份正式发布商用。', '[{"title":"阿里云百炼","url":"https://bailian.console.aliyun.com/"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007013', '2026-04-21-huawei-ai-glasses', '华为发布首款鸿蒙 AI 眼镜：1200万超感光摄像头', '产品发布', '2026-04-21', '华为正式发布首款鸿蒙 AI 眼镜，搭载 1200 万超感光摄像头，支持 AI 构图矫正、0.7s 超清晰 AI 闪拍，内置小艺智能体，可提供 AI 实时视频交互及"看一下"支付功能。', '[{"title":"华为官网","url":"https://www.huawei.com"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007014', '2026-04-21-bytedance-2025-revenue', '字节跳动2025海外营收占比超三成，AI投入致净利降70%', '行业动态', '2026-04-21', '2025年字节跳动海外营收增长近 50%，占比提升至超三成。但因去年三四季度大幅增加 AI 业务投入，净利润降幅超 70%。抖音副总裁回应称，净利润下滑受优先股和期权成本变动影响。', '[{"title":"字节跳动官网","url":"https://www.bytedance.com"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007015', '2026-04-21-iqiyi-ai-artist-library', '爱奇艺「AI艺人库」引争议，多位艺人否认授权', '行业动态', '2026-04-21', '爱奇艺推出"AI艺人库"计划，声称超100位艺人入驻以创建数字分身。但多位艺人迅速否认签署授权协议，引发了关于AI技术在娱乐行业应用合规性及艺人权益保护的讨论。', '[{"title":"爱奇艺官网","url":"https://www.iqiyi.com"}]');
INSERT OR REPLACE INTO news (uid, slug, title, category, publishedAt, context, refUrl) VALUES ('9007016', '2026-04-21-vercel-hacked', 'Vercel遭黑客入侵，第三方AI工具成攻击突破口', '行业动态', '2026-04-21', 'Vercel证实发生安全事件，黑客通过遭入侵的第三方AI工具实施攻击，窃取了部分员工数据。调查确认事件源于第三方AI工具的谷歌云端工作区OAuth应用遭入侵。', '[{"title":"Vercel 官网","url":"https://vercel.com"},{"title":"Vercel 安全公告","url":"https://vercel.com/blog/security-incident"}]');